window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c1d5bf05df6fab6"]={"versions": [{"id": "FIG-9c1d5bf05df6fab6", "releases": ["R4.0.3", "R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm illustriert ein Anti-Pattern bzw. eine ungültige Modellierungskonstellation für Delegations-Konnektoren (<code>DelegationSwConnector</code>) an den Begrenzungen einer übergeordneten <code>CompositionSwComponentType</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Umfassender Rahmen eines <code>CompositionSwComponentType</code> mit einem äußeren Eingangs-Port (P-Port bzw. R-Port mit nach innen gerichtetem Pfeildreieck / Datenflussrichtung nach innen).\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei getrennte innere <code>SwComponentPrototype</code>-Instanzen (grau hinterlegte Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Verfügt über einen Eingangs-Port mit der Schnittstellenelementmenge <code>{A, B}</code>.\n</li><li>Untere Komponente: Verfügt über einen Eingangs-Port mit der Schnittstellenelementmenge <code>{B, C, E}</code>.\n</li></ul>\n</li><li><strong>Konnektoren</strong>: Zwei <code>DelegationSwConnector</code>-Verbindungszweige, die beide von demselben einzelnen äußeren Port ausgehen und sich fächerförmig auf die beiden Eingangs-Ports der inneren Komponenten aufteilen.\n</li><li><strong>Annotation</strong>: Ein zentral platziertes, unzufriedenes Smiley-Symbol („Sad Face“) kennzeichnet die dargestellte Konnektorkonfiguration als unzulässig.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architekturmodellierung ohne Sequenz- oder Zeitablauf. Dargestellt ist der Versuch einer Verteilung bzw. eines Splits von Datenströmen oder Serviceaufrufen: Eingehende Kommunikationsdaten am äußeren Port sollen über verzweigte Delegation Connectors parallel auf zwei verschiedene Ziel-Ports aufgeteilt werden. Da die Ziel-Ports unterschiedliche Elementmengen aufweisen (<code>{A, B}</code> und <code>{B, C, E}</code>), liegt eine nicht standardkonforme Aufteilung vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Konfiguration gemäß AUTOSAR-Spezifikation (TPS Software Component Template). Ein Delegations-Konnektor darf an einem übergeordneten Port nicht illegal aufgespalten werden („Illegal split of delegation connector“). Entwickler und Modellierungswerkzeuge müssen sicherstellen, dass Delegationsverbindungen zwischen äußeren Ports einer Komposition und inneren Ports von Prototypen eineindeutige und typkompatible Schnittstellen-Mappings einhalten; ein impliziter Split an einem Außen-Port auf Subkomponenten mit partiell divergierenden Datenelementen <code>{A, B}</code> und <code>{B, C, E}</code> verletzt die Konsistenzregeln für <code>DelegationSwConnector</code>.</p>"}, {"id": "FIG-fd1598f272631d05", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm stellt ein Anti-Pattern bezüglich der Verzweigung und Mehrfachverbindung von Delegations-Konnektoren (<code>DelegationSwConnector</code>) innerhalb eines <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Ein umfassender Rahmen (<code>CompositionSwComponentType</code>) mit drei separaten äußeren Ports am linken Rand (jeweils mit abgeschnittenen Interfacesymbolen <code>{...}</code> am Rand):\n<ul class=\"fig-list\"><li>Oberer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der oberen inneren Komponente verbunden.\n</li><li>Mittlerer Außen-Port: Verzweigt sich über zwei diagonale <code>DelegationSwConnector</code>-Linien auf die Eingangs-Ports beider inneren Komponenten.\n</li><li>Unterer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der unteren inneren Komponente verbunden.\n</li></ul>\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei innere <code>SwComponentPrototype</code>-Instanzen (graue Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{A, B}</code>, der von zwei Konnektoren (oberer und mittlerer Außen-Port) angesteuert wird.\n</li><li>Untere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{B, C}</code>, der von zwei Konnektoren (mittlerer und unterer Außen-Port) angesteuert wird.\n</li></ul>\n</li><li><strong>Annotation</strong>: Zentrales Smiley-Symbol („Sad Face“), das die Gesamtkonstellation der Verzweigung und Mehrfachanbindung als unzulässig markiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Zeitachse. Veranschaulicht wird der Versuch, sowohl individuelle 1:1-Delegationen (oberer und unterer Außen-Port) als auch eine parallele 1:n-Aufspaltung ausgehend vom mittleren Außen-Port auf dieselben internen Ports mit den Schnittstelleninhalten <code>{A, B}</code> bzw. <code>{B, C}</code> zu führen. Dies führt an beiden Ziel-Ports zu kollidierenden Mehrfachanbindungen (Split und Join über Delegation Connectors).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Modellierungskonstellation. Die Verzweigung eines Delegations-Konnektors vom mittleren Außen-Port auf zwei verschiedene innere Komponenten-Ports (<code>{A, B}</code> und <code>{B, C}</code>) in Kombination mit simultanen Einzel-Delegationen auf dieselben Ziel-Ports („Illegal split of delegation connector“) verletzt die AUTOSAR-Modellierungsregeln für <code>DelegationSwConnector</code>. Ein einzelner Port darf Delegationen nicht in dieser Form aufspalten oder überlappend zusammenführen, da Schnittstellenkompatibilität und eindeutiges Routing verletzt werden.</p>"}, {"id": "FIG-1c338b632e2a8b88", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm stellt ein Anti-Pattern bezüglich der Verzweigung und Mehrfachverbindung von Delegations-Konnektoren (<code>DelegationSwConnector</code>) innerhalb eines <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Ein umfassender Rahmen (<code>CompositionSwComponentType</code>) mit drei separaten äußeren Ports am linken Rand (jeweils mit abgeschnittenen Interfacesymbolen <code>{...}</code> am Rand):\n<ul class=\"fig-list\"><li>Oberer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der oberen inneren Komponente verbunden.\n</li><li>Mittlerer Außen-Port: Verzweigt sich über zwei diagonale <code>DelegationSwConnector</code>-Linien auf die Eingangs-Ports beider inneren Komponenten.\n</li><li>Unterer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der unteren inneren Komponente verbunden.\n</li></ul>\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei innere <code>SwComponentPrototype</code>-Instanzen (graue Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{A, B}</code>, der von zwei Konnektoren (oberer und mittlerer Außen-Port) angesteuert wird.\n</li><li>Untere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{B, C}</code>, der von zwei Konnektoren (mittlerer und unterer Außen-Port) angesteuert wird.\n</li></ul>\n</li><li><strong>Annotation</strong>: Zentrales Smiley-Symbol („Sad Face“), das die Gesamtkonstellation der Verzweigung und Mehrfachanbindung als unzulässig markiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Zeitachse. Veranschaulicht wird der Versuch, sowohl individuelle 1:1-Delegationen (oberer und unterer Außen-Port) als auch eine parallele 1:n-Aufspaltung ausgehend vom mittleren Außen-Port auf dieselben internen Ports mit den Schnittstelleninhalten <code>{A, B}</code> bzw. <code>{B, C}</code> zu führen. Dies führt an beiden Ziel-Ports zu kollidierenden Mehrfachanbindungen (Split und Join über Delegation Connectors).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Modellierungskonstellation. Die Verzweigung eines Delegations-Konnektors vom mittleren Außen-Port auf zwei verschiedene innere Komponenten-Ports (<code>{A, B}</code> und <code>{B, C}</code>) in Kombination mit simultanen Einzel-Delegationen auf dieselben Ziel-Ports („Illegal split of delegation connector“) verletzt die AUTOSAR-Modellierungsregeln für <code>DelegationSwConnector</code>. Ein einzelner Port darf Delegationen nicht in dieser Form aufspalten oder überlappend zusammenführen, da Schnittstellenkompatibilität und eindeutiges Routing verletzt werden.</p>"}, {"id": "FIG-fcd0b06a70f05c36", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm stellt ein Anti-Pattern bezüglich der Verzweigung und Mehrfachverbindung von Delegations-Konnektoren (<code>DelegationSwConnector</code>) innerhalb eines <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Ein umfassender Rahmen (<code>CompositionSwComponentType</code>) mit drei separaten äußeren Ports am linken Rand (jeweils mit abgeschnittenen Interfacesymbolen <code>{...}</code> am Rand):\n<ul class=\"fig-list\"><li>Oberer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der oberen inneren Komponente verbunden.\n</li><li>Mittlerer Außen-Port: Verzweigt sich über zwei diagonale <code>DelegationSwConnector</code>-Linien auf die Eingangs-Ports beider inneren Komponenten.\n</li><li>Unterer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der unteren inneren Komponente verbunden.\n</li></ul>\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei innere <code>SwComponentPrototype</code>-Instanzen (graue Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{A, B}</code>, der von zwei Konnektoren (oberer und mittlerer Außen-Port) angesteuert wird.\n</li><li>Untere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{B, C}</code>, der von zwei Konnektoren (mittlerer und unterer Außen-Port) angesteuert wird.\n</li></ul>\n</li><li><strong>Annotation</strong>: Zentrales Smiley-Symbol („Sad Face“), das die Gesamtkonstellation der Verzweigung und Mehrfachanbindung als unzulässig markiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Zeitachse. Veranschaulicht wird der Versuch, sowohl individuelle 1:1-Delegationen (oberer und unterer Außen-Port) als auch eine parallele 1:n-Aufspaltung ausgehend vom mittleren Außen-Port auf dieselben internen Ports mit den Schnittstelleninhalten <code>{A, B}</code> bzw. <code>{B, C}</code> zu führen. Dies führt an beiden Ziel-Ports zu kollidierenden Mehrfachanbindungen (Split und Join über Delegation Connectors).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Modellierungskonstellation. Die Verzweigung eines Delegations-Konnektors vom mittleren Außen-Port auf zwei verschiedene innere Komponenten-Ports (<code>{A, B}</code> und <code>{B, C}</code>) in Kombination mit simultanen Einzel-Delegationen auf dieselben Ziel-Ports („Illegal split of delegation connector“) verletzt die AUTOSAR-Modellierungsregeln für <code>DelegationSwConnector</code>. Ein einzelner Port darf Delegationen nicht in dieser Form aufspalten oder überlappend zusammenführen, da Schnittstellenkompatibilität und eindeutiges Routing verletzt werden.</p>"}, {"id": "FIG-dee8fc617754c2cb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm stellt ein Anti-Pattern bezüglich der Verzweigung und Mehrfachverbindung von Delegations-Konnektoren (<code>DelegationSwConnector</code>) innerhalb eines <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Ein umfassender Rahmen (<code>CompositionSwComponentType</code>) mit drei separaten äußeren Ports am linken Rand (jeweils mit abgeschnittenen Interfacesymbolen <code>{...}</code> am Rand):\n<ul class=\"fig-list\"><li>Oberer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der oberen inneren Komponente verbunden.\n</li><li>Mittlerer Außen-Port: Verzweigt sich über zwei diagonale <code>DelegationSwConnector</code>-Linien auf die Eingangs-Ports beider inneren Komponenten.\n</li><li>Unterer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der unteren inneren Komponente verbunden.\n</li></ul>\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei innere <code>SwComponentPrototype</code>-Instanzen (graue Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{A, B}</code>, der von zwei Konnektoren (oberer und mittlerer Außen-Port) angesteuert wird.\n</li><li>Untere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{B, C}</code>, der von zwei Konnektoren (mittlerer und unterer Außen-Port) angesteuert wird.\n</li></ul>\n</li><li><strong>Annotation</strong>: Zentrales Smiley-Symbol („Sad Face“), das die Gesamtkonstellation der Verzweigung und Mehrfachanbindung als unzulässig markiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Zeitachse. Veranschaulicht wird der Versuch, sowohl individuelle 1:1-Delegationen (oberer und unterer Außen-Port) als auch eine parallele 1:n-Aufspaltung ausgehend vom mittleren Außen-Port auf dieselben internen Ports mit den Schnittstelleninhalten <code>{A, B}</code> bzw. <code>{B, C}</code> zu führen. Dies führt an beiden Ziel-Ports zu kollidierenden Mehrfachanbindungen (Split und Join über Delegation Connectors).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Modellierungskonstellation. Die Verzweigung eines Delegations-Konnektors vom mittleren Außen-Port auf zwei verschiedene innere Komponenten-Ports (<code>{A, B}</code> und <code>{B, C}</code>) in Kombination mit simultanen Einzel-Delegationen auf dieselben Ziel-Ports („Illegal split of delegation connector“) verletzt die AUTOSAR-Modellierungsregeln für <code>DelegationSwConnector</code>. Ein einzelner Port darf Delegationen nicht in dieser Form aufspalten oder überlappend zusammenführen, da Schnittstellenkompatibilität und eindeutiges Routing verletzt werden.</p>"}, {"id": "FIG-f6184c46ba21c1d9", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositionsdiagramm zur Architekturebene der AUTOSAR Classic Platform (Software Component Template). Das Diagramm stellt ein Anti-Pattern bezüglich der Verzweigung und Mehrfachverbindung von Delegations-Konnektoren (<code>DelegationSwConnector</code>) innerhalb eines <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Komponente</strong>: Ein umfassender Rahmen (<code>CompositionSwComponentType</code>) mit drei separaten äußeren Ports am linken Rand (jeweils mit abgeschnittenen Interfacesymbolen <code>{...}</code> am Rand):\n<ul class=\"fig-list\"><li>Oberer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der oberen inneren Komponente verbunden.\n</li><li>Mittlerer Außen-Port: Verzweigt sich über zwei diagonale <code>DelegationSwConnector</code>-Linien auf die Eingangs-Ports beider inneren Komponenten.\n</li><li>Unterer Außen-Port: Über einen horizontalen <code>DelegationSwConnector</code> mit dem Eingangs-Port der unteren inneren Komponente verbunden.\n</li></ul>\n</li><li><strong>Integrierte Software-Komponenten</strong>: Zwei innere <code>SwComponentPrototype</code>-Instanzen (graue Rechtecke).\n<ul class=\"fig-list\"><li>Obere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{A, B}</code>, der von zwei Konnektoren (oberer und mittlerer Außen-Port) angesteuert wird.\n</li><li>Untere Komponente: Eingangs-Port mit annotierter Schnittstellenelementmenge <code>{B, C}</code>, der von zwei Konnektoren (mittlerer und unterer Außen-Port) angesteuert wird.\n</li></ul>\n</li><li><strong>Annotation</strong>: Zentrales Smiley-Symbol („Sad Face“), das die Gesamtkonstellation der Verzweigung und Mehrfachanbindung als unzulässig markiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Zeitachse. Veranschaulicht wird der Versuch, sowohl individuelle 1:1-Delegationen (oberer und unterer Außen-Port) als auch eine parallele 1:n-Aufspaltung ausgehend vom mittleren Außen-Port auf dieselben internen Ports mit den Schnittstelleninhalten <code>{A, B}</code> bzw. <code>{B, C}</code> zu führen. Dies führt an beiden Ziel-Ports zu kollidierenden Mehrfachanbindungen (Split und Join über Delegation Connectors).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ unzulässige Modellierungskonstellation. Die Verzweigung eines Delegations-Konnektors vom mittleren Außen-Port auf zwei verschiedene innere Komponenten-Ports (<code>{A, B}</code> und <code>{B, C}</code>) in Kombination mit simultanen Einzel-Delegationen auf dieselben Ziel-Ports („Illegal split of delegation connector“) verletzt die AUTOSAR-Modellierungsregeln für <code>DelegationSwConnector</code>. Ein einzelner Port darf Delegationen nicht in dieser Form aufspalten oder überlappend zusammenführen, da Schnittstellenkompatibilität und eindeutiges Routing verletzt werden.</p>"}, {"id": "FIG-60739f4cf4fc1f7e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Kompositionsdiagramm (Software Component Template). Das Diagramm visualisiert die unzulässige strukturelle Verschaltung von Ports zwischen einer umgebenden <code>CompositionSwComponentType</code> und enthaltenen <code>SwComponentPrototype</code>-Instanzen über Delegation Connectors (<code>DelegationSwConnector</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Äußere Komponente (<code>CompositionSwComponentType</code>): Besitzt drei Eingangsports (Required Ports, <code>RPortPrototype</code>), jeweils typisiert oder annotiert mit den Datenelementen bzw. Signalen <code>{A}</code>, <code>{B}</code> und <code>{C}</code>.\n</li><li>Innere Komponenten (<code>SwComponentPrototype</code>): Zwei gekapselte Software-Komponentenprototypen (graue Blöcke) mit jeweils einem Required Port. Der obere Port erwartet die Elemente <code>{A, B}</code>, der untere Port <code>{B, C}</code>.\n</li><li>Konnektoren (<code>DelegationSwConnector</code>):\n<ul class=\"fig-list\"><li>Der äußere Port <code>{A}</code> verbindet sich mit dem oberen inneren Port <code>{A, B}</code>.\n</li><li>Der äußere Port <code>{B}</code> verzweigt sich unzulässig (Split) auf beide inneren Ports (<code>{A, B}</code> und <code>{B, C}</code>).\n</li><li>Der äußere Port <code>{C}</code> verbindet sich mit dem unteren inneren Port <code>{B, C}</code>.\n</li></ul>\n</li><li>Ein Smiley-Piktogramm (trauriges Gesicht) kennzeichnet die dargestellte Modellierungskonstellation als ungültig/Fehlerfall.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schnittstellendiagramm ohne Laufzeitsequenz. Eingehende Datenströme oder Ereignisse am äußeren Port <code>{B}</code> müssten gemäß der Konnektordefinition simultan an zwei unterschiedliche Zielports der inneren Komponenteninstanzen propagiert werden, während die jeweiligen Zielports gleichzeitig Teilelemente aus separaten Quellports (<code>{A}</code> bzw. <code>{C}</code>) beziehen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert ein Negativbeispiel für die Port-Delegation (Illegal Split): Die Verzweigung eines einzelnen äußeren Delegation Ports auf mehrere innere Ports in Kombination mit überlappender Signal-/Elementzusammensetzung ist nach den AUTOSAR-Modellierungsregeln unzulässig (<code>[constr_...]</code>). Ein solcher Split eines <code>DelegationSwConnector</code> führt zu Validierungsfehlern im Software-Architekturmodell und kann vom RTE-Generator nicht deterministisch aufgelöst werden. Modellierer müssen Schnittstellen entweder auf Kompositionsebene eindeutig bündeln oder separate Ports verwenden.</p>"}, {"id": "FIG-0601d803c32409cc", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Kompositionsdiagramm (Software Component Template). Das Diagramm visualisiert ein Negativbeispiel für die unzulässige Verzweigung eines <code>DelegationSwConnector</code> von einem äußeren Port einer <code>CompositionSwComponentType</code> auf mehrere innere <code>SwComponentPrototype</code>-Instanzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Äußere Komponente (<code>CompositionSwComponentType</code>): Besitzt genau einen gemeinsamen Eingangsport (Required Port, <code>RPortPrototype</code>).\n</li><li>Innere Komponenten (<code>SwComponentPrototype</code>): Zwei gekapselte Software-Komponentenprototypen (graue Blöcke) mit je einem Required Port:\n<ul class=\"fig-list\"><li>Oberer Port: annotiert mit der Elementmenge <code>{A, B}</code>.\n</li><li>Unterer Port: annotiert mit der Elementmenge <code>{B, C, E}</code>.\n</li></ul>\n</li><li>Konnektoren (<code>DelegationSwConnector</code>): Vom einzelnen äußeren Eingangsport verzweigen zwei Delegationsverbindungen (1-zu-n Split) auf die beiden inneren Ports <code>{A, B}</code> und <code>{B, C, E}</code>.\n</li><li>Ein Smiley-Piktogramm (trauriges Gesicht) im Zentrum markiert diese Verbindungstopologie als unzulässig.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne zeitlichen Sequenzablauf. Es zeigt den Versuch, einen einzelnen eingehenden Delegationspfad auf Architecturebene auf zwei separate Zielports mit unterschiedlichen Schnittstellenmengen (<code>{A, B}</code> und <code>{B, C, E}</code>) aufzuspalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht eine verbotene Modellierungskonstellation (Illegal split of delegation connector). Ein 1-zu-n-Split eines eingehenden Delegation-Connectors auf mehrere innerbetriebliche Empfängerports mit disjunkten bzw. teilüberlappenden Elementsätzen verletzt die Integritätsregeln für AUTOSAR-Softwarekomponenten. Dies führt zu Inkompatibilitäten bei der Port-Kopplung und Fehlern bei der RTE-Generierung, da die Datenkonsistenz und Schnittstellendeklaration auf Delegationsebene nicht eindeutig aufgelöst werden kann.</p>"}], "trans": []};
